#include <bits/stdc++.h>
using namespace std;

class Solution {public:int totalStrength(vector<int>& a){const long long MOD=1000000007;int n=a.size();vector<int> L(n),R(n),st;for(int i=0;i<n;++i){while(!st.empty()&&a[st.back()]>=a[i])st.pop_back();L[i]=st.empty()?-1:st.back();st.push_back(i);}st.clear();for(int i=n-1;i>=0;--i){while(!st.empty()&&a[st.back()]>a[i])st.pop_back();R[i]=st.empty()?n:st.back();st.push_back(i);}vector<long long> p(n+1),pp(n+2);for(int i=0;i<n;++i)p[i+1]=(p[i]+a[i])%MOD;for(int i=0;i<=n;++i)pp[i+1]=(pp[i]+p[i])%MOD;long long ans=0;for(int i=0;i<n;++i){long long right=(pp[R[i]+1]-pp[i+1]+MOD)%MOD,left=(pp[i+1]-pp[L[i]+1]+MOD)%MOD;long long contribution=(right*(i-L[i])%MOD-left*(R[i]-i)%MOD+MOD)%MOD;ans=(ans+a[i]*contribution)%MOD;}return (int)ans;} };
